package com.example.statusdrafter.repository; import com.example.statusdrafter.entity.User; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface UserRepository extends JpaRepository<User,Long>{Optional<User> findByUsername(String username); Optional<User> findByEmail(String email); List<User> findByRole(User.Role role); long countByRole(User.Role role);}
